CREATE TABLE lateral_parents (id INTEGER PRIMARY KEY, label VARCHAR(12), payload JSONB);
CREATE TABLE lateral_children (id INTEGER PRIMARY KEY, parent_id INTEGER, occurred TIMESTAMPTZ, amount INTEGER);
INSERT INTO lateral_parents VALUES (1, 'one', '{"items":[1,2]}'), (2, NULL, '{"items":[]}'), (3, 'three', NULL), (4, 'four', '{"items":[3]}');
INSERT INTO lateral_children VALUES (10, 1, '2024-01-01 12:00:00+00', 3), (11, 1, '2024-01-02 12:00:00+00', NULL), (12, 1, '2024-01-03 12:00:00+00', 5), (20, 2, '2024-01-01 12:00:00+00', -1);
SELECT p.id, x.id, x.amount FROM lateral_parents p CROSS JOIN LATERAL (SELECT c.id, c.amount FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id LIMIT 2) x ORDER BY p.id, x.id;
SELECT p.id, x.id FROM lateral_parents p LEFT JOIN LATERAL (SELECT c.id FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id DESC LIMIT 1) x ON TRUE ORDER BY p.id;
SELECT p.id, x.amount FROM lateral_parents p JOIN LATERAL (SELECT c.amount FROM lateral_children c WHERE c.parent_id = p.id) x ON x.amount > 0 ORDER BY p.id, x.amount;
SELECT p.id, x.amount FROM lateral_parents p LEFT JOIN LATERAL (SELECT c.amount FROM lateral_children c WHERE c.parent_id = p.id) x ON x.amount > 100 ORDER BY p.id;
SELECT p.id, x.total, x.n FROM lateral_parents p, LATERAL (SELECT sum(c.amount) AS total, count(*) AS n FROM lateral_children c WHERE c.parent_id = p.id) x ORDER BY p.id;
SELECT p.id, x.id, y.v FROM lateral_parents p, LATERAL (SELECT p.id) x, LATERAL (SELECT x.id + 1 AS v) y ORDER BY p.id;
SELECT p.id, x.label FROM lateral_parents p CROSS JOIN LATERAL (SELECT p.label) x ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p CROSS JOIN LATERAL (VALUES (p.id), (p.id + 1)) x(v) ORDER BY p.id, x.v;
SELECT p.id, x.id FROM lateral_parents p LEFT JOIN LATERAL (SELECT c.id FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id LIMIT p.id OFFSET p.id - 1) x ON TRUE ORDER BY p.id, x.id;
SELECT p.id, x.day FROM lateral_parents p LEFT JOIN LATERAL (SELECT date_trunc('day', c.occurred) AS day FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id DESC LIMIT 1) x ON TRUE ORDER BY p.id;
SELECT p.id, x.value FROM lateral_parents p LEFT JOIN LATERAL (SELECT j.value FROM jsonb_array_elements(p.payload -> 'items') AS j(value)) x ON TRUE ORDER BY p.id, x.value;
WITH parents AS (SELECT * FROM lateral_parents) SELECT p.id, x.id FROM parents p LEFT JOIN LATERAL (SELECT c.id FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id LIMIT 1) x ON TRUE ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p CROSS JOIN LATERAL (WITH chosen AS (SELECT c.amount FROM lateral_children c WHERE c.parent_id = p.id) SELECT sum(amount) AS v FROM chosen) x ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p CROSS JOIN LATERAL (SELECT (SELECT p.id + 1) AS v) x ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p CROSS JOIN LATERAL (SELECT y.v FROM (VALUES (2)) a(n) CROSS JOIN LATERAL (SELECT p.id + a.n AS v) y) x ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p CROSS JOIN LATERAL (SELECT p.id AS v FROM lateral_children p ORDER BY p.id LIMIT 1) x ORDER BY p.id;
SELECT p.id, x.id FROM lateral_parents p RIGHT JOIN LATERAL (SELECT c.id FROM lateral_children c) x ON p.id = x.id ORDER BY x.id;
SELECT p.id, x.id FROM lateral_parents p FULL JOIN LATERAL (SELECT c.id FROM lateral_children c) x ON p.id = x.id ORDER BY p.id, x.id;
CREATE SEQUENCE lateral_seq;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS (SELECT p.id AS v), z AS (WITH a AS (SELECT v + 10 AS v FROM y) SELECT v FROM a) SELECT v FROM z) x ORDER BY p.id;
CREATE SEQUENCE lateral_idle_filter;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT (SELECT nextval('lateral_idle_filter')) AS n WHERE p.id < 0 OFFSET 0) x ORDER BY p.id;
SELECT nextval('lateral_idle_filter');
CREATE SEQUENCE lateral_idle_case;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT CASE WHEN p.id < 0 THEN (SELECT nextval('lateral_idle_case')) ELSE 0 END AS n OFFSET 0) x ORDER BY p.id;
SELECT nextval('lateral_idle_case');
CREATE SEQUENCE lateral_idle_coalesce;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT coalesce(p.id::bigint, (SELECT nextval('lateral_idle_coalesce'))) AS n OFFSET 0) x ORDER BY p.id;
SELECT nextval('lateral_idle_coalesce');
CREATE SEQUENCE lateral_idle_cte;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS MATERIALIZED (SELECT nextval('lateral_idle_cte') n) SELECT y.n FROM y WHERE p.id < 0 OFFSET 0) x ORDER BY p.id;
SELECT nextval('lateral_idle_cte');
CREATE SEQUENCE lateral_idle_recursive;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH RECURSIVE y(n, k) AS (SELECT nextval('lateral_idle_recursive'), 1 UNION ALL SELECT n, k + 1 FROM y WHERE k < 2) SELECT n, p.id FROM y WHERE p.id < 0 OFFSET 0) x ORDER BY p.id;
SELECT nextval('lateral_idle_recursive');
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS (SELECT 10 AS v WHERE p.id = 1) SELECT v FROM y) x ORDER BY p.id;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT (SELECT 10 WHERE p.id = 1) AS v) x ORDER BY p.id;
SELECT p.id, x.v FROM (VALUES (0), (1)) p(id) CROSS JOIN LATERAL (SELECT (SELECT 10 LIMIT p.id) AS v) x ORDER BY p.id;
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT (SELECT nextval('lateral_seq')) AS n, p.id OFFSET 0) x ORDER BY p.id;
SELECT currval('lateral_seq');
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH RECURSIVE y(n, k) AS (SELECT nextval('lateral_seq'), 1 UNION ALL SELECT n, k + 1 FROM y WHERE k < 2) SELECT n, p.id FROM y OFFSET 0) x ORDER BY p.id, x.n;
SELECT currval('lateral_seq');
SELECT p.id, x.n, x.k FROM (VALUES (1), (3), (2)) p(id) CROSS JOIN LATERAL (WITH RECURSIVE y(n, k) AS (SELECT nextval('lateral_seq'), 1 UNION ALL SELECT n, k + 1 FROM y) SELECT n, k FROM y LIMIT p.id) x ORDER BY p.id, x.k;
SELECT currval('lateral_seq');
SELECT p.id, x.n FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS MATERIALIZED (SELECT nextval('lateral_seq') AS n) SELECT y.n, p.id FROM y OFFSET 0) x ORDER BY p.id;
SELECT currval('lateral_seq');
SELECT p.id, x.n FROM lateral_parents p CROSS JOIN LATERAL (SELECT nextval('lateral_seq') AS n, p.id AS parent_id OFFSET 0) x ORDER BY p.id;
SELECT currval('lateral_seq');
SELECT p.id, x.n FROM lateral_parents p CROSS JOIN LATERAL (SELECT nextval('lateral_seq') AS n OFFSET 0) x ORDER BY p.id;
SELECT currval('lateral_seq');
CREATE VIEW lateral_latest AS SELECT p.id, x.amount FROM lateral_parents p LEFT JOIN LATERAL (SELECT c.amount FROM lateral_children c WHERE c.parent_id = p.id ORDER BY c.id DESC LIMIT 1) x ON TRUE;
SELECT * FROM lateral_latest ORDER BY id;
SELECT p.id, x.label FROM lateral_parents p CROSS JOIN LATERAL (SELECT p.*) x ORDER BY p.id;
SELECT p.id, v FROM lateral_parents p CROSS JOIN LATERAL (SELECT p.id + 1 AS v) ORDER BY p.id;
SELECT p.id, x.v FROM lateral_parents p LEFT JOIN (lateral_children c CROSS JOIN LATERAL (SELECT p.id + c.id AS v) x) ON c.parent_id = p.id ORDER BY p.id, x.v;
SELECT p.id, x.id FROM lateral_parents p, LATERAL (SELECT c.id FROM lateral_children c WHERE FALSE) x, LATERAL (SELECT x.id) y;
SELECT p.id, x.n FROM (VALUES (1), (1)) p(id) CROSS JOIN LATERAL (SELECT y.n FROM (SELECT nextval('lateral_seq') n, p.id) y OFFSET 0) x;
SELECT currval('lateral_seq');
SELECT p.id, x.n FROM (VALUES (1), (1)) p(id) CROSS JOIN LATERAL (WITH y AS MATERIALIZED (SELECT nextval('lateral_seq') n, p.id) SELECT n FROM y) x;
SELECT currval('lateral_seq');
SELECT p.id, x.id FROM (VALUES (1)) p(id) CROSS JOIN LATERAL (SELECT p.id FROM (VALUES (2)) p(id) UNION ALL SELECT p.id) x;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS (SELECT p.id AS v) SELECT v FROM y) x ORDER BY p.id;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH RECURSIVE y(v) AS (SELECT p.id UNION ALL SELECT v + 1 FROM y WHERE v < 3) SELECT v FROM y) x ORDER BY p.id, x.v;
CREATE TABLE lateral_shadow (v INTEGER);
INSERT INTO lateral_shadow VALUES (10);
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH lateral_shadow AS (SELECT p.id + v AS v FROM lateral_shadow), z AS (SELECT v FROM lateral_shadow) SELECT v FROM z) x ORDER BY p.id;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (SELECT (WITH y AS (SELECT p.id AS v) SELECT v FROM y) AS v) x ORDER BY p.id;
SELECT p.id, x.v FROM (VALUES (1), (2)) p(id) CROSS JOIN LATERAL (WITH y AS (SELECT p.id AS v) SELECT z.v FROM (WITH y AS (SELECT v + 10 AS v FROM y) SELECT v FROM y) z) x ORDER BY p.id;
